// 1. Captura a lista completa de todas as transações acumuladas que o loop finalizou
const transacoes = $('Loop Over Items').all();
const faturasAgrupadas = {};

// Varre todas as transações já categorizadas e agrupa por Banco, Mês e Ano
for (const t of transacoes) {
  const dados = t.json;

  // Cria uma chave única para cada fatura (ex: "Nubank-maio-2026")
  const chaveFatura = `${dados.banco}-${dados.mes_referencia}-${dados.ano_referencia}`;

  if (!faturasAgrupadas[chaveFatura]) {
    faturasAgrupadas[chaveFatura] = {
      banco: dados.banco,
      mes_referencia: dados.mes_referencia,
      ano_referencia: dados.ano_referencia,
      valor_total: 0,
      compras: []
    };
  }

  // Força o valor a virar número decimal puro
  const valorNum = parseFloat(dados.valor) || 0;

  faturasAgrupadas[chaveFatura].valor_total += valorNum;
  faturasAgrupadas[chaveFatura].compras.push({
    estabelecimento: dados.estabelecimento,
    valor: valorNum,
    // Pega a categoria gerada pela IA (se por acaso falhar, assume 'Compras')
    categoria: dados.categoria || "Compras" 
  });
}

// 2. Transforma os grupos nos textos formatados em HTML para o Telegram
const output = [];

for (const chave in faturasAgrupadas) {
  const fatura = faturasAgrupadas[chave];

  let textoTelegram = `📦 <b>Fatura Salva com Sucesso!</b>\n\n`;
  textoTelegram += `🏦 <b>Banco:</b> ${fatura.banco.toUpperCase()}\n`;
  textoTelegram += `📅 <b>Referência:</b> ${fatura.mes_referencia}/${fatura.ano_referencia}\n`;
  textoTelegram += `💵 <b>Valor Total:</b> R$ ${fatura.valor_total.toFixed(2).replace('.', ',')}\n\n`;
  textoTelegram += `🛒 <b>Resumo dos Gastos:</b>\n`;

  // Adiciona cada compra do respectivo mês na listagem trazendo a categoria da IA
  for (const compra of fatura.compras) {
    const valorFormatado = compra.valor.toFixed(2).replace('.', ',');
    textoTelegram += `• <code>${compra.estabelecimento}</code> [${compra.categoria}]: R$ ${valorFormatado}\n`;
  }

  textoTelegram += `\n⚙️ <i>Status: Armazenado no PostgreSQL. Transações repetidas foram ignoradas via Upsert.</i>`;

  // Injeta no formato de saída padrão do n8n
  output.push({
    json: {
      banco: fatura.banco,
      mes_referencia: fatura.mes_referencia,
      ano_referencia: fatura.ano_referencia,
      mensagem_final: textoTelegram
    }
  });
}

return output;

const items = typeof $input !== 'undefined' ? $input.all() : [];
const output = [];

// Função auxiliar para converter os meses textuais (abreviados) para número (01 a 12)
function converterMesParaNumero(mesStr) {
  const meses = {
    jan: "01", fev: "02", mar: "03", abr: "04", mai: "05", jun: "06",
    jul: "07", ago: "08", set: "09", out: "10", nov: "11", dez: "12"
  };
  const busca = mesStr.toLowerCase().substring(0, 3);
  return meses[busca] || "01";
}

// Função auxiliar para limpar o nome do estabelecimento de forma segura
function limparEstabelecimento(nome) {
  return nome
    .replace(/\n/g, ' ')                                      // Transforma quebras de linha em espaço
    .replace(/\s+/g, ' ')                                     // Remove espaços duplos
    .replace(/PAG\*/gi, '')                                   // Remove apenas o prefixo "PAG*" específico
    .replace(/EBN\s*\*|DL\s*\*|DI\s*\*/gi, '')                // Remove intermediários comuns incluindo o "DI*" do HBO
    .replace(/\*/g, ' ')                                      // Substitui qualquer asterisco restante por espaço
    .replace(/\s+/g, ' ')                                     // Remove espaços duplos que sobraram das remoções
    .trim();                                                  // Remove espaços no início e fim
}

for (const item of items) {
  const text = item.json.text || "";

  // ----------------------------------------------------
  // EXTRAÇÃO NUBANK
  // ----------------------------------------------------
  if (text.includes("Nubank") || text.includes("Olá, Artur.\nEsta é a sua fatura de")) {
    let mes_referencia = null;
    let ano_referencia = "2026"; 

    const mesMatch = text.match(/fatura de\s*\n?([a-zA-Záàâãéèêíïóôõöúç]+)/i);
    if (mesMatch) mes_referencia = mesMatch[1].trim().toLowerCase();

    const anoMatch = text.match(/vencimento:\s*\d+\s*[A-Z]{3}\s*([\d]{4})/i);
    if (anoMatch) ano_referencia = anoMatch[1];

    const regexTransacao = /(\d{2}\s+[A-Z]{3})\s*\n?••••\s*\d{4}\s+([\s\S]*?)\s+R\$\s+([\d.,]+)/g;
    let match;

    while ((match = regexTransacao.exec(text)) !== null) {
      const data_resumida = match[1].trim();
      const estabelecimento_bruto = match[2];
      const valor_str = match[3];
      const valor = parseFloat(valor_str.replace('.', '').replace(',', '.'));

      // Aplica a limpeza segura
      const estabelecimento = limparEstabelecimento(estabelecimento_bruto);

      const [dia, mesTexto] = data_resumida.split(/\s+/);
      const mesNum = converterMesParaNumero(mesTexto);
      const data_iso = `${ano_referencia}-${mesNum}-${dia.padStart(2, '0')}`;

      output.push({
        json: {
          banco: "Nubank",
          mes_referencia,
          ano_referencia,
          data_transacao: data_iso,
          estabelecimento,
          valor
        }
      });
    }
  } 

  // ----------------------------------------------------
  // EXTRAÇÃO PICPAY
  // ----------------------------------------------------
  else if (text.includes("PicPay") || text.includes("Picpay")) {
    let mes_referencia = null;
    let ano_referencia = "2026";

    const mesMatch = text.match(/fatura de\s*([a-zA-Záàâãéèêíïóôõöúç]+)/i);
    if (mesMatch) mes_referencia = mesMatch[1].trim().toLowerCase();

    const anoMatch = text.match(/Vencimento\s*\n?\d{2}\/\d{2}\/([\d]{4})/i);
    if (anoMatch) ano_referencia = anoMatch[1];

    const regexTransacao = /(\d{2}\/\d{2})\s+([\s\S]*?)\s+([\d.,]+)\n/g;
    let match;

    while ((match = regexTransacao.exec(text)) !== null) {
      const data_resumida = match[1].trim();
      const estabelecimento_bruto = match[2];
      const valor_str = match[3];

      if (estabelecimento_bruto.toLowerCase().includes("estabelecimento") || 
          estabelecimento_bruto.toLowerCase().includes("subtotal") || 
          estabelecimento_bruto.toLowerCase().includes("total geral")) {
        continue;
      }

      const valor = parseFloat(valor_str.replace('.', '').replace(',', '.'));

      // Aplica a limpeza segura
      const estabelecimento = limparEstabelecimento(estabelecimento_bruto);

      if (!estabelecimento) continue;

      const [dia, mesNum] = data_resumida.split('/');
      const data_iso = `${ano_referencia}-${mesNum.padStart(2, '0')}-${dia.padStart(2, '0')}`;

      output.push({
        json: {
          banco: "PicPay",
          mes_referencia,
          ano_referencia,
          data_transacao: data_iso,
          estabelecimento,
          valor
        }
      });
    }
  }
}

return output;

// 1. Pega os dados totais extraídos do PDF (ex: 121 itens)
const extraidas = $("Extrair PDF").all();

const existentes = $('Execute a SQL query').all();

const chavesExistentes = new Set(
  existentes.map(item => {
    const valorNum = parseFloat(item.json.valor).toFixed(2);
    return `${item.json.banco}|${item.json.data_transacao}|${item.json.estabelecimento}|${valorNum}`;
  })
);

const ineditas = [];

for (const t of extraidas) {
  const dados = t.json;
  const valorFormatado = dados.valor.toFixed(2);
  const chave = `${dados.banco}|${dados.data_transacao}|${dados.estabelecimento}|${valorFormatado}`;

  if (!chavesExistentes.has(chave)) {
    ineditas.push({ json: dados });
  }
}

return ineditas;
